entries.body:
(From \cite{LWX126}, Proposition 2.5.)


Consider $f: X\to Y$, $x\in E_\infty^{s,t}(X)$, $y\in E_\infty^{s+n,t+n}(Y)$ and $y'\in E_\infty^{s+m,t+m}(Y)$ for $m,n\ge 0$.
\begin{enumerate}
    \item[(1)] There is an $f$-extension from $x$ to $y$, i.e., $d_n^{f}(x)=y$ in the $f$-ESS if and only if there is a class $[x]\in \{x\}$ such that $f[x]\in \{y\}$.
    \item[(2)] An $f$-extension from $x$ to $y$ is inessential, i.e., $y$ is trivial in the $E_n$-page of the $f$-ESS if and only if there exists an element $x'\in E_\infty^{s+a,t+a}(X)$ for $0<a\le n$ such that we have an essential differential $d_{n-a}^{f}(x')=y$. Equivalently, there exists a class $[x'] \in \{x'\} \subset \pi_*X$ with AF$(x')>$AF$(x)$, such that $f[x'] \in \{y\}$.

    \item[(3)] Suppose we have an $f$-extension from $x$ to both $y$ and $y'$.
    \begin{enumerate}
        \item[(1)] If $m=n$, then $y-y'\in \BESS{f}^{s+n,t+n}_{n-1}(Y)$ and there exists an element $x'\in E_\infty^{s+a,t+a}(X)$ for $0<a\le n$ such that we have an essential differential 
        $$d_{n-a}^{f}(x') = y-y'$$
        in $f$-ESS. Equivalently, there exists a class $[x'] \in \{x'\} \subset \pi_*X$ with AF$(x')>$AF$(x)$, such that $f[x'] \in \{y-y'\}$. 
        \item[(2)] If $m>n$, then the $f$-extension from $x$ to $y$ is inessential.
     \end{enumerate}
\end{enumerate}

